## Setup ----
testthat::skip_if(
  Sys.getenv("RUN_SLOW_TESTS") != "true",
  "Skipping: RUN_SLOW_TESTS is not set to true."
)

make_vonb_parameters <- function(fims_frame) {
  default_parameters <- FIMS::setup_default_parameters(data = fims_frame)

  default_parameters |>
    dplyr::filter(.data[["module_name"]] != "Growth") |>
    dplyr::bind_rows(
      FIMS::setup_default_Growth(
        data = fims_frame,
        module_type = "VonBertalanffySchnute"
      )
    )
}

make_vonb_convergence_context <- function() {
  data("data_big", package = "FIMS")
  fims_frame <- FIMS::FIMSFrame(data_big)

  parameters <- make_vonb_parameters(fims_frame)

  list(
    data = fims_frame,
    parameters = parameters
  )
}

make_vonb_no_age_to_length_conversion_fixed_context <- function() {
  data("data_big", package = "FIMS")
  no_age_to_length_conversion_fixed_data <- data_big |>
    dplyr::filter(type != "age_to_length_conversion")
  fims_frame <- FIMS::FIMSFrame(no_age_to_length_conversion_fixed_data)

  parameters <- make_vonb_parameters(fims_frame)

  list(
    data = fims_frame,
    parameters = parameters
  )
}

make_vonb_explicit_length_bin_context <- function() {
  data("data_big", package = "FIMS")
  survey1_short_bins <- seq(0, 550, 50)
  survey1_bins <- tibble::tibble(
    type = "length_bin",
    fleet = "survey1",
    age = NA_real_,
    length = survey1_short_bins,
    observed = NA_real_,
    unit = unique(data_big$unit[which(data_big$fleet == "survey1")])[1],
    timing = NA_real_,
    uncertainty = NA_character_
  )

  custom_data <- data_big |>
    dplyr::filter(
      !(
        .data[["fleet"]] == "survey1" &
          .data[["type"]] == "length_comp" &
          !is.na(.data[["length"]]) &
          !(.data[["length"]] %in% survey1_short_bins)
      )
    ) |>
    dplyr::bind_rows(survey1_bins) |>
    dplyr::group_by(fleet, type, timing) |>
    dplyr::mutate(
      observed = dplyr::if_else(
        fleet == "survey1" & type == "length_comp",
        observed / sum(observed, na.rm = TRUE),
        observed
      )
    ) |>
    dplyr::ungroup()
  fims_frame <- FIMS::FIMSFrame(custom_data)

  parameters <- make_vonb_parameters(fims_frame)

  list(
    data = fims_frame,
    parameters = parameters,
    explicit_bins = survey1_short_bins
  )
}

