make_vonb_length_bin_only_context <- function() {
  data("data_big", package = "FIMS")

  fleet1_bins <- data_big |>
    dplyr::filter(
      .data[["fleet"]] == "fleet1",
      .data[["type"]] == "length_comp",
      !is.na(.data[["length"]])
    ) |>
    dplyr::pull(.data[["length"]]) |>
    unique() |>
    sort()

  fleet1_length_bins <- tibble::tibble(
    type = "length_bin",
    fleet = "fleet1",
    age = NA_real_,
    length = fleet1_bins,
    observed = NA_real_,
    unit = unique(data_big$unit[which(data_big$fleet == "fleet1")])[1],
    timing = NA_real_,
    uncertainty = NA_character_
  )

  custom_data <- data_big |>
    dplyr::filter(
      !(.data[["type"]] %in% c("length_comp", "age_to_length_conversion"))
    ) |>
    dplyr::bind_rows(fleet1_length_bins)

  fims_frame <- FIMS::FIMSFrame(custom_data)
  parameters <- make_vonb_parameters(fims_frame)

  list(
    data = fims_frame,
    parameters = parameters,
    explicit_bins = fleet1_bins
  )
}

make_vonb_model_comparison_context <- function() {
  data("data_big", package = "FIMS")
  fims_frame <- FIMS::FIMSFrame(data_big)

  # Keep the Model Comparison parameters for non-recruitment, non-growth,
  # non-population structural parameters only. Drop old Data rows because
  # current main uses parsed uncertainty strings rather than Data rows in the
  # parameter table. parameters_big divides the estimated values by
  # initial_value_scale, so multiply to start at the OM values.
  initial_value_scale <- readRDS(
    testthat::test_path("fixtures", "initial_value_scale.RDS")
  )
  base_parameters <- FIMS::parameters_big |>
    dplyr::mutate(
      value = dplyr::if_else(
        estimation_type != "constant",
        value * initial_value_scale,
        value
      )
    ) |>
    dplyr::filter(
      !module_name %in% c("Data", "Growth", "Recruitment", "Population")
    )

  current_growth_recruitment <- make_vonb_parameters(fims_frame) |>
    dplyr::filter(module_name %in% c("Growth", "Recruitment", "Population"))

  list(
    data = fims_frame,
    parameters = dplyr::bind_rows(base_parameters, current_growth_recruitment)
  )
}

# A fleet's length bins and the weights that rebin the population length grid
# to them, from the model data that initialize_fims() builds. The model maps
# ages to the fleet's lengths through these weights, 1 column per fleet bin.
initialize_test_fleet <- function(parameters, data, fleet) {
  fleet_data <- FIMS::initialize_fims(parameters = parameters, data = data)[[
    "model_data"
  ]][["fleets"]][[fleet]]
  list(
    lengths = fleet_data[["length_bins"]],
    rebin_weights = fleet_data[["rebin_weights"]]
  )
}

## IO correctness ----
test_that("reference lengths survive initialization across estimation settings", {
  ctx <- make_vonb_convergence_context()
  settings <- expand.grid(
    young = c("constant", "fixed_effects"),
    old = c("constant", "fixed_effects"),
    stringsAsFactors = FALSE
  )

  for (i in seq_len(nrow(settings))) {
    parameters <- ctx$parameters |>
      dplyr::mutate(
        estimation_type = dplyr::case_when(
          module_name == "Growth" & label == "mean_length_young" ~
            settings$young[i],
          module_name == "Growth" & label == "mean_length_old" ~
            settings$old[i],
          TRUE ~ estimation_type
        )
      )

    fit <- parameters |>
      FIMS::initialize_fims(data = ctx$data) |>
      FIMS::fit_fims(optimize = FALSE, get_sd = FALSE)

    lengths <- FIMS::get_estimates(fit) |>
      dplyr::filter(
        module_name == "Growth",
        label %in% c("mean_length_young", "mean_length_old")
      )
    case <- paste("young:", settings$young[i], "old:", settings$old[i])

    #' @description Finalized reference lengths equal their physical inputs for all constant/fixed-effect combinations.
    expect_equal(
      lengths$estimated,
      lengths$input,
      tolerance = 1e-6,
      info = case
    )

    #' @description Backend length at the youngest reference age equals the supplied younger length.
    expect_equal(
      as.numeric(FIMS::get_report(fit)[["growth_mean_LAA"]][[1]][1]),
      lengths$input[lengths$label == "mean_length_young"],
      tolerance = 1e-8,
      info = case
    )
  }
})

test_that("von bertalanffy growth converges when L1 L2 and K are estimable", {
  ctx <- make_vonb_convergence_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  input <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data)

  fit <- FIMS::fit_fims(
    input = input,
    report_age_to_length_conversion_derived = TRUE,
    optimize = TRUE,
    number_of_loops = 4,
    number_of_newton_steps = 0,
    get_sd = FALSE
  )

  report <- FIMS::get_report(fit)
  growth_estimates <- FIMS::get_estimates(fit) |>
    dplyr::filter(module_name == "Growth")
  core_growth_estimates <- growth_estimates |>
    dplyr::filter(label %in% c(
      "mean_length_young",
      "mean_length_old",
      "growth_coefficient"
    )) |>
    dplyr::arrange(match(
      label,
      c("mean_length_young", "mean_length_old", "growth_coefficient")
    )) |>
    dplyr::pull(estimated)

  #' @description Test that the von Bertalanffy--Schnute growth fit reaches a small maximum gradient under the current non-Newton optimization path.
  # Allow small cross-platform optimizer jitter while still requiring a low
  # gradient for the growth-estimation integration test.
  expect_lte(FIMS::get_max_gradient(fit), 1e-2)

  #' @description Test that the estimable von Bertalanffy--Schnute growth parameters remain finite and positive.
  expect_true(all(is.finite(core_growth_estimates)))
  expect_true(all(core_growth_estimates > 0))

  #' @description Test that the second reference length stays larger than the first.
  expect_gt(
    growth_estimates |>
      dplyr::filter(label == "mean_length_old") |>
      dplyr::pull(estimated),
    growth_estimates |>
      dplyr::filter(label == "mean_length_young") |>
      dplyr::pull(estimated)
  )

  #' @description Test that reported SD at length-at-age remains positive for the fitted von Bertalanffy--Schnute path.
  expect_true(all(
    report[["growth_sd_LAA"]][[1]] > 0
  ))

  #' @description Test that the fitted fleet reports using the growth-derived age-to-length conversion path.
  expect_equal(
    report[["age_to_length_conversion_derived_used"]][[1]][1],
    1
  )

  #' @description Test that the active growth-derived age-to-length conversion path does not also
  #' report a legacy fixed age_to_length_conversion matrix.
  expect_equal(length(report[["age_to_length_conversion"]][[1]]), 0)

  #' @description Test that both biological and fleet-mapped mean WAA remain finite on the dynamic von Bertalanffy--Schnute path.
  expect_true(all(is.finite(
    report[["growth_mean_WAA"]][[1]]
  )))
  expect_true(all(is.finite(
    report[["growth_derived_mean_WAA"]][[1]]
  )))
  expect_equal(
    length(report[["growth_mean_WAA"]][[1]]),
    length(report[["growth_derived_mean_WAA"]][[1]])
  )

  #' @description Test that objective-side index weight_at_age uses the biological population mean WAA on the refactored von Bertalanffy--Schnute path.
  fleet_index_numbers_at_age <- report[["index_numbers_at_age"]][[1]]
  fleet_index_weight_at_age <- report[["index_weight_at_age"]][[1]]
  population_mean_waa <- report[["growth_mean_WAA"]][[1]]
  positive_index_cells <- abs(fleet_index_numbers_at_age) > 0
  expect_true(any(positive_index_cells))
  expect_equal(
    fleet_index_weight_at_age[positive_index_cells] /
      fleet_index_numbers_at_age[positive_index_cells],
    population_mean_waa[positive_index_cells],
    tolerance = 1e-8
  )

  #' @description Test that objective-side catch weight_at_age uses the biological population mean WAA on the refactored von Bertalanffy--Schnute path.
  fleet_catch_numbers_at_age <- report[["catch_numbers_at_age"]][[1]]
  fleet_catch_weight_at_age <- report[["catch_weight_at_age"]][[1]]
  positive_catch_cells <- abs(fleet_catch_numbers_at_age) > 0
  expect_true(any(positive_catch_cells))
  expect_equal(
    fleet_catch_weight_at_age[positive_catch_cells] /
      fleet_catch_numbers_at_age[positive_catch_cells],
    population_mean_waa[positive_catch_cells],
    tolerance = 1e-8
  )

  #' @description Test that biological mean WAA is weight averaged over the length-at-age distribution, a (mu^3 + 3 mu sd^2) for b = 3, not weight at the mean length.
  length_weight_a <- growth_estimates |>
    dplyr::filter(.data[["label"]] == "length_weight_a") |>
    dplyr::pull(.data[["estimated"]])
  length_weight_b <- growth_estimates |>
    dplyr::filter(.data[["label"]] == "length_weight_b") |>
    dplyr::pull(.data[["estimated"]])
  expect_equal(length_weight_b, 3)
  mean_laa <- report[["growth_mean_LAA"]][[1]]
  sd_laa <- report[["growth_sd_LAA"]][[1]]
  expected_mean_waa <- length_weight_a *
    (mean_laa^3 + 3 * mean_laa * sd_laa^2)
  expect_lt(max(abs(population_mean_waa / expected_mean_waa - 1)), 1e-3)
  expect_true(all(population_mean_waa > length_weight_a * mean_laa^3))

  realized_age_to_length_conversion <- report[["age_to_length_conversion_derived"]][[1]]
  n_years <- FIMS::get_n_years(ctx$data)
  n_ages <- FIMS::get_n_ages(ctx$data)
  fleet1_obj <- initialize_test_fleet(
    parameters = ctx$parameters,
    data = ctx$data,
    fleet = "fleet1"
  )
  n_lengths <- length(fleet1_obj[["lengths"]])
  realized_age_to_length_conversion_array <- array(
    realized_age_to_length_conversion,
    dim = c(n_lengths, n_ages, n_years)
  )

  #' @description Test that the realized growth-derived age-to-length conversion rows sum to one for each year and age.
  expect_true(all(abs(apply(realized_age_to_length_conversion_array, c(2, 3), sum) - 1) < 1e-5))
})

test_that("von bertalanffy growth estimates stay close to Model Comparison OM growth values", {
  ctx <- make_vonb_model_comparison_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  # Model Comparison base-case OM values from save_initial_input.R
  Linf <- 800
  K <- 0.18
  a0 <- -1.36

  # Same von Bertalanffy--Schnute formula used in the model comparison OM data generator.
  AtoL <- function(a, Linf, K, a0) {
    Linf * (1 - exp(-K * (a - a0)))
  }

  expected_growth <- tibble::tibble(
    label = c(
      "mean_length_young",
      "mean_length_old",
      "growth_coefficient"
    ),
    expected = c(
      AtoL(1, Linf, K, a0),
      AtoL(12, Linf, K, a0),
      K
    )
  )

  input <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data)

  fit <- FIMS::fit_fims(
    input = input,
    report_age_to_length_conversion_derived = TRUE,
    optimize = TRUE,
    number_of_loops = 2,
    number_of_newton_steps = 0,
    get_sd = FALSE
  )

  #' @description Test that the von Bertalanffy--Schnute fit against Model Comparison OM values converges normally.
  expect_equal(FIMS::get_opt(fit)$convergence, 0)

  #' @description Test that the von Bertalanffy--Schnute fit against Model Comparison OM values reaches a small maximum gradient.
  expect_lte(FIMS::get_max_gradient(fit), 0.01)

  growth_estimates <- FIMS::get_estimates(fit) |>
    dplyr::filter(
      module_name == "Growth",
      label %in% expected_growth$label
    ) |>
    dplyr::select(label, estimated) |>
    dplyr::left_join(expected_growth, by = "label")

  #' @description Test that the fitted von Bertalanffy--Schnute output includes the three Model Comparison OM-truth growth parameters.
  expect_setequal(growth_estimates$label, expected_growth$label)

  # The bound is in mm. Reading the length labels half a bin off (25 mm for
  # the 50 mm bins in data_big) fails it.
  #' @description Test that fitted mean_length_young remains within 2 mm of the Model Comparison OM value at age 1.
  expect_lte(
    abs(
      growth_estimates |>
        dplyr::filter(label == "mean_length_young") |>
        dplyr::pull(estimated) -
        growth_estimates |>
        dplyr::filter(label == "mean_length_young") |>
        dplyr::pull(expected)
    ),
    2
  )

  #' @description Test that fitted mean_length_old remains within 2 mm of the Model Comparison OM value at age 12.
  expect_lte(
    abs(
      growth_estimates |>
        dplyr::filter(label == "mean_length_old") |>
        dplyr::pull(estimated) -
        growth_estimates |>
        dplyr::filter(label == "mean_length_old") |>
        dplyr::pull(expected)
    ),
    2
  )

  #' @description Test that fitted growth_coefficient remains within 0.01 of the Model Comparison OM growth coefficient.
  expect_lte(
    abs(
      growth_estimates |>
        dplyr::filter(label == "growth_coefficient") |>
        dplyr::pull(estimated) -
        growth_estimates |>
        dplyr::filter(label == "growth_coefficient") |>
        dplyr::pull(expected)
    ),
    0.01
  )
})

test_that("von bertalanffy report defaults to lightweight derived age-to-length conversion diagnostics", {
  ctx <- make_vonb_convergence_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  fit <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data) |>
    FIMS::fit_fims(optimize = FALSE)

  report <- FIMS::get_report(fit)

  sd_labels <- c("length_at_age_sd_young", "length_at_age_sd_old")
  supplied_sd <- ctx$parameters |>
    dplyr::filter(module_name == "Growth", label %in% sd_labels) |>
    dplyr::arrange(match(label, sd_labels)) |>
    dplyr::pull(value)

  reported_sd <- FIMS::get_estimates(fit) |>
    dplyr::filter(module_name == "Growth", label %in% sd_labels) |>
    dplyr::arrange(match(label, sd_labels))

  #' @description Finalized Growth reporting preserves both named SDs in physical length units before optimization.
  expect_equal(reported_sd$label, sd_labels)
  expect_equal(reported_sd$estimated, supplied_sd, tolerance = 1e-8)

  reference_labels <- c(
    "reference_age_for_length_young",
    "reference_age_for_length_old"
  )
  reference_ages <- ctx$parameters |>
    dplyr::filter(module_name == "Growth", label %in% reference_labels) |>
    dplyr::arrange(match(label, reference_labels)) |>
    dplyr::pull(value)

  reference_indices <- match(reference_ages, FIMS::get_ages(ctx$data))

  #' @description Backend SD-at-age recovers the supplied SDs at the two reference ages.
  expect_equal(
    as.numeric(report[["growth_sd_LAA"]][[1]])[reference_indices],
    supplied_sd,
    tolerance = 1e-6
  )

  #' @description Test that the derived von Bertalanffy--Schnute path is still selected in reports by default.
  expect_equal(report[["age_to_length_conversion_derived_used"]][[1]][1], 1)

  #' @description Test that default reporting keeps fleet growth-derived mean WAA available.
  expect_gt(length(report[["growth_derived_mean_WAA"]][[1]]), 0)

  #' @description Test that default reporting does not materialize the full derived age-to-length conversion tensor.
  expect_equal(length(report[["age_to_length_conversion_derived"]][[1]]), 0)
})

test_that("von bertalanffy uses fleet length-comp bins when fixed fleet age-to-length conversion rows are absent", {
  ctx <- make_vonb_no_age_to_length_conversion_fixed_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  fit <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data) |>
    FIMS::fit_fims(optimize = FALSE)

  report <- FIMS::get_report(fit)
  fleet_obj <- initialize_test_fleet(
    parameters = ctx$parameters,
    data = ctx$data,
    fleet = "fleet1"
  )
  fleet1_lengthcomp_bins <- ctx$data |>
    FIMS::get_data() |>
    dplyr::filter(
      fleet == "fleet1",
      type == "length_comp",
      !is.na(length)
    ) |>
    dplyr::pull(length) |>
    unique() |>
    sort()

  #' @description Test that the growth-derived age-to-length conversion path is selected when von Bertalanffy--Schnute growth is used without fixed fleet age-to-length conversion rows.
  expect_equal(report[["age_to_length_conversion_derived_used"]][[1]][1], 1)

  #' @description Test that no fixed age_to_length_conversion matrix is reported when the fleet relies only on the growth-derived age-to-length conversion path.
  expect_equal(length(report[["age_to_length_conversion"]][[1]]), 0)

  #' @description Test that fleet initialization falls back to the observed length-comp bins when fixed age-to-length conversion rows are absent.
  expect_equal(fleet_obj[["lengths"]], fleet1_lengthcomp_bins)
  #' @description Test that the model maps ages to 1 column per observed length-comp bin of the fleet.
  expect_equal(
    ncol(fleet_obj[["rebin_weights"]]),
    length(fleet1_lengthcomp_bins)
  )
  #' @description Test that the expected length composition has 1 value per year and observed length-comp bin of the fleet.
  expect_length(
    report[["lengthcomp_proportion"]][[1]],
    FIMS::get_n_years(ctx$data) * length(fleet1_lengthcomp_bins)
  )

  #' @description Test that growth-derived mean WAA is still reported when the fleet relies on the length-comp bin fallback.
  expect_gt(length(report[["growth_derived_mean_WAA"]][[1]]), 0)
})

test_that("von bertalanffy keeps explicit length_bin geometry when fixed age-to-length conversion rows are also present", {
  expect_no_warning(ctx <- make_vonb_explicit_length_bin_context())
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  fit <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data) |>
    FIMS::fit_fims(optimize = FALSE)

  report <- FIMS::get_report(fit)
  fleet_obj <- initialize_test_fleet(
    parameters = ctx$parameters,
    data = ctx$data,
    fleet = "survey1"
  )

  #' @description Test that explicit `length_bin` rows are used even when fixed age-to-length rows are present.
  expect_equal(fleet_obj[["lengths"]], ctx$explicit_bins)

  #' @description Test that the model maps ages to 1 column per explicit `length_bin` of survey1.
  expect_equal(
    ncol(fleet_obj[["rebin_weights"]]),
    length(ctx[["explicit_bins"]])
  )

  #' @description Test that the expected survey1 length composition has 1 value per year and explicit `length_bin`.
  expect_length(
    report[["lengthcomp_proportion"]][[2]],
    FIMS::get_n_years(ctx$data) * length(ctx[["explicit_bins"]])
  )

  #' @description Test that the growth-derived age-to-length conversion path is still active when explicit fleet bins are present.
  expect_equal(report[["age_to_length_conversion_derived_used"]][[1]][1], 1)

  #' @description Test that the growth-derived path does not fall back to a legacy fixed age-to-length matrix.
  expect_equal(length(report[["age_to_length_conversion"]][[1]]), 0)
})

test_that("von bertalanffy can use explicit length_bin geometry without length compositions", {
  ctx <- make_vonb_length_bin_only_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  input <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data)

  fit <- FIMS::fit_fims(
    input = input,
    report_age_to_length_conversion_derived = TRUE,
    optimize = FALSE,
    get_sd = FALSE
  )

  report <- FIMS::get_report(fit)
  fleet_obj <- initialize_test_fleet(
    parameters = ctx$parameters,
    data = ctx$data,
    fleet = "fleet1"
  )

  #' @description Test that explicit `length_bin` rows set the fleet's length bins when there are no length compositions.
  expect_equal(fleet_obj[["lengths"]], ctx[["explicit_bins"]])
  #' @description Test that the model maps ages to 1 column per explicit `length_bin` when there are no length compositions.
  expect_equal(
    ncol(fleet_obj[["rebin_weights"]]),
    length(ctx[["explicit_bins"]])
  )
  #' @description Test that the expected length composition has 1 value per year and explicit `length_bin`, with no length compositions to fit.
  expect_length(
    report[["lengthcomp_proportion"]][[1]],
    FIMS::get_n_years(ctx$data) * length(ctx[["explicit_bins"]])
  )
  #' @description Test that the growth-derived age-to-length conversion path is used for explicit `length_bin` rows without length compositions.
  expect_true(any(report[["age_to_length_conversion_derived_used"]][[1]] == 1))
  #' @description Test that the growth-derived age-to-length conversion is reported when requested.
  expect_gt(length(report[["age_to_length_conversion_derived"]][[1]]), 0)
})

test_that("default non-derived growth keeps the historical fixed age-to-length conversion path", {
  ctx <- make_default_growth_age_to_length_conversion_fixed_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  fit <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data) |>
    FIMS::fit_fims(optimize = FALSE)

  report <- FIMS::get_report(fit)

  #' @description Test that the fixed age_to_length_conversion matrix is present for the historical non-derived growth path.
  expect_gt(length(report[["age_to_length_conversion"]][[1]]), 0)

  #' @description Test that the non-derived growth path reports no growth-derived age-to-length conversion usage.
  expect_equal(report[["age_to_length_conversion_derived_used"]][[1]][1], 0)

  #' @description Test that no realized growth-derived age-to-length conversion tensor is produced for the fixed historical path.
  expect_equal(length(report[["age_to_length_conversion_derived"]][[1]]), 0)
})

test_that("von bertalanffy Newton polishing does not worsen objective or gradient", {
  skip(
    paste(
      "Newton steps are currently not implemented in `fit_fims()`.",
      "See the note in `R/fimsfit.R` above the",
      "`number_of_newton_steps > 0` guard."
    )
  )

  ctx <- make_vonb_convergence_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  fit_base <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data) |>
    FIMS::fit_fims(
      optimize = TRUE,
      get_sd = FALSE,
      number_of_newton_steps = 0
    )
  base_objective <- FIMS::get_opt(fit_base)$objective
  base_max_gradient <- FIMS::get_max_gradient(fit_base)
  rm(fit_base)
  gc()

  fit_newton <- ctx$parameters |>
    FIMS::initialize_fims(data = ctx$data) |>
    FIMS::fit_fims(
      optimize = TRUE,
      get_sd = FALSE,
      number_of_newton_steps = 1
    )
  newton_objective <- FIMS::get_opt(fit_newton)$objective
  newton_max_gradient <- FIMS::get_max_gradient(fit_newton)

  #' @description Test that optional Newton polishing does not worsen the optimized objective.
  expect_lte(
    newton_objective,
    base_objective + 1e-8
  )

  #' @description Test that optional Newton polishing does not worsen the maximum gradient.
  expect_lte(
    newton_max_gradient,
    base_max_gradient
  )
})

test_that("fleet-specific length bins set the size of each fleet's age-to-length key", {
  expect_no_warning(ctx <- make_two_fleet_length_context())
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  fleet1_obj <- initialize_test_fleet(
    parameters = ctx$parameters,
    data = ctx$data,
    fleet = "fleet1"
  )
  fleet_short_obj <- initialize_test_fleet(
    parameters = ctx$parameters,
    data = ctx$data,
    fleet = "survey1"
  )

  fleet1_lengths <- fleet1_obj[["lengths"]]
  fleet_short_lengths <- fleet_short_obj[["lengths"]]

  #' @description Test that the model maps fleet1's ages to 1 column per fleet1 length bin.
  expect_equal(ncol(fleet1_obj[["rebin_weights"]]), length(fleet1_lengths))
  #' @description Test that the model maps survey1's ages to 1 column per survey1 length bin.
  expect_equal(
    ncol(fleet_short_obj[["rebin_weights"]]),
    length(fleet_short_lengths)
  )

  #' @description Test that survey1 keeps its own length bins, 0 to 550 by 50, rather than fleet1's.
  expect_equal(fleet_short_lengths, seq(0, 550, 50))
  #' @description Test that fleet1 keeps its own length bins, 0 to 1100 by 50.
  expect_equal(fleet1_lengths, seq(0, 1100, 50))

  lengthcomp1_values <- FIMS:::read_length_comp(
    ctx$data, "fleet1", fleet1_lengths
  )
  lengthcomp2_values <- suppressWarnings(
    FIMS:::read_length_comp(ctx$data, "survey1", fleet_short_lengths)
  )

  #' @description Test that each fleet's length-composition module matches its own length-comp data rows.
  expect_equal(
    lengthcomp1_values,
    ctx$data |>
      FIMS::get_data() |>
      dplyr::filter(type == "length_comp", fleet == "fleet1") |>
      dplyr::mutate(
        sample_size = dplyr::if_else(
          observed == -999,
          1,
          unlist(
            FIMS:::parse_data_distribution(uncertainty)$size,
            use.names = FALSE
          )
        ),
        out = dplyr::if_else(
          unit == "number",
          observed,
          observed * sample_size
        )
      ) |>
      dplyr::pull(out)
  )

  #' @description Test that survey1's length compositions keep only the rows in its own length bins.
  expect_equal(
    lengthcomp2_values,
    ctx$data |>
      FIMS::get_data() |>
      dplyr::filter(
        type == "length_comp",
        fleet == "survey1",
        length %in% fleet_short_lengths
      ) |>
      dplyr::mutate(
        sample_size = dplyr::if_else(
          observed == -999,
          1,
          unlist(
            FIMS:::parse_data_distribution(uncertainty)$size,
            use.names = FALSE
          )
        ),
        out = dplyr::if_else(
          unit == "number",
          observed,
          observed * sample_size
        )
      ) |>
      dplyr::pull(out)
  )
})

test_that("von bertalanffy standard errors are on the scale of the estimates", {
  ctx <- make_vonb_convergence_context()
  # The standard deviation of the back-transformed value, from many draws of
  # the working-scale estimate, checks the delta method without using it.
  draw_sd <- function(estimate, standard_error, back_transform) {
    set.seed(20261107)
    stats::sd(back_transform(stats::rnorm(1e5, estimate, standard_error)))
  }
  working_scale_value <- function(fit, label) {
    sdreport <- FIMS::get_sdreport(fit)
    name <- grep(paste0("^Growth[.]", label, "[.]"),
      names(sdreport[["par.fixed"]]),
      value = TRUE
    )
    c(
      estimate = sdreport[["par.fixed"]][[name]],
      standard_error = sqrt(diag(sdreport[["cov.fixed"]]))[[name]]
    )
  }
  growth_row <- function(fit, label) {
    FIMS::get_estimates(fit) |>
      dplyr::filter(module_name == "Growth", label == .env[["label"]])
  }

  fit <- suppressWarnings(
    ctx[["parameters"]] |>
      FIMS::initialize_fims(data = ctx[["data"]]) |>
      FIMS::fit_fims()
  )
  for (label in c("mean_length_young", "mean_length_old", "growth_coefficient")) {
    working <- working_scale_value(fit, paste0("log_", label))
    #' @description Test that each log-scale growth parameter's standard error in `get_estimates()` matches the spread of its back-transformed draws.
    expect_equal(
      object = growth_row(fit, label)[["uncertainty"]],
      expected = draw_sd(working[["estimate"]], working[["standard_error"]], exp),
      tolerance = 0.01
    )
  }

  # With L2 constant, L1 is estimated on a logit scale bounded by 0 and L2.
  fixed_l2_parameters <- ctx[["parameters"]] |>
    dplyr::mutate(estimation_type = dplyr::if_else(
      module_name == "Growth" & label == "mean_length_old",
      "constant", estimation_type
    ))
  fixed_l2_fit <- suppressWarnings(
    fixed_l2_parameters |>
      FIMS::initialize_fims(data = ctx[["data"]]) |>
      FIMS::fit_fims()
  )
  mean_length_old <- growth_row(fixed_l2_fit, "mean_length_old")[["estimated"]]
  working <- working_scale_value(fixed_l2_fit, "logit_mean_length_young")
  #' @description Test that the logit-scale L1 standard error in `get_estimates()` matches the spread of its back-transformed draws.
  expect_equal(
    object = growth_row(fixed_l2_fit, "mean_length_young")[["uncertainty"]],
    expected = draw_sd(
      working[["estimate"]], working[["standard_error"]],
      function(x) FIMS::inv_logit(0, mean_length_old, x)
    ),
    tolerance = 0.01
  )
})
