## Error handling ----
test_that("von bertalanffy initialization rejects decreasing reference lengths", {
  ctx <- make_vonb_convergence_context()
  on.exit(
    {
      rm(ctx)
      gc()
    },
    add = TRUE
  )

  bad_parameters <- ctx$parameters |>
    dplyr::mutate(
      value = dplyr::case_when(
        module_name == "Growth" & label == "mean_length_young" ~ 800,
        module_name == "Growth" & label == "mean_length_old" ~ 700,
        TRUE ~ value
      )
    )

  #' @description Test that von Bertalanffy--Schnute initialization rejects a second reference length smaller than the first.
  expect_error(
    bad_parameters |>
      FIMS::initialize_fims(data = ctx$data),
    regexp = "mean_length_old must be > mean_length_young"
  )
})
